function write(root, filePath, content) {
  const fullPath = join(root, filePath);
  mkdirSync(dirname(fullPath), { recursive: true });
  writeFileSync(fullPath, content);
}

function run(root) {
  return spawnSync(process.execPath, [scriptPath, "--root", root], {
    cwd: root,
    encoding: "utf8",
  });
}

